    return makePrepared({prompt,stimulus:raw.stimulus||"",choices:["I only","II only","Both I and II","Neither I nor II"],answer:0,explanation:`Response I is correct and response II is not correct in this context. ${raw.explanation}`},r,catId,`${seed}:${baseIndex}:v${variant}`);
